macro_rules! deps {
    () => {
        FlatSet!();
        ValueHint!();
        Flag!();
        ArgAction!();
        Command!();
        Arg!();
    };
}

macro_rules! assert_app {
    () => {
        deps!();
        pub (crate) fn assert_app (cmd : & Command) { debug ! ("Command::_debug_asserts") ; let mut short_flags = vec ! [] ; let mut long_flags = vec ! [] ; if cmd . get_version () . is_none () && cmd . get_long_version () . is_none () { assert ! (! cmd . is_propagate_version_set () , "Command {}: No version information via Command::version or Command::long_version to propagate" , cmd . get_name () ,) ; let version_needed = cmd . get_arguments () . filter (| x | matches ! (x . get_action () , ArgAction :: Version)) . map (| x | x . get_id ()) . collect :: < Vec < _ > > () ; assert_eq ! (version_needed , Vec ::<& str >:: new () , "Command {}: `ArgAction::Version` used without providing Command::version or Command::long_version" , cmd . get_name ()) ; } for sc in cmd . get_subcommands () { if let Some (s) = sc . get_short_flag () . as_ref () { short_flags . push (Flag :: Command (format ! ("-{s}") , sc . get_name ())) ; } for short_alias in sc . get_all_short_flag_aliases () { short_flags . push (Flag :: Command (format ! ("-{short_alias}") , sc . get_name ())) ; } if let Some (l) = sc . get_long_flag () . as_ref () { assert ! (! l . starts_with ('-') , "Command {}: long_flag {:?} must not start with a `-`, that will be handled by the parser" , sc . get_name () , l) ; long_flags . push (Flag :: Command (format ! ("--{l}") , sc . get_name ())) ; } for long_alias in sc . get_all_long_flag_aliases () { long_flags . push (Flag :: Command (format ! ("--{long_alias}") , sc . get_name ())) ; } } for arg in cmd . get_arguments () { assert_arg (arg) ; assert ! (! cmd . is_multicall_set () , "Command {}: Arguments like {} cannot be set on a multicall command" , cmd . get_name () , arg . get_id ()) ; if let Some (s) = arg . get_short () { short_flags . push (Flag :: Arg (format ! ("-{s}") , arg . get_id () . as_str ())) ; } for (short_alias , _) in & arg . short_aliases { short_flags . push (Flag :: Arg (format ! ("-{short_alias}") , arg . get_id () . as_str ())) ; } if let Some (l) = arg . get_long () { assert ! (! l . starts_with ('-') , "Argument {}: long {:?} must not start with a `-`, that will be handled by the parser" , arg . get_id () , l) ; long_flags . push (Flag :: Arg (format ! ("--{l}") , arg . get_id () . as_str ())) ; } for (long_alias , _) in & arg . aliases { long_flags . push (Flag :: Arg (format ! ("--{long_alias}") , arg . get_id () . as_str ())) ; } if let Some ((first , second)) = cmd . two_args_of (| x | x . get_id () == arg . get_id ()) { panic ! ("Command {}: Argument names must be unique, but '{}' is in use by more than one argument or group{}" , cmd . get_name () , arg . get_id () , duplicate_tip (cmd , first , second) ,) ; } if let Some (l) = arg . get_long () { if let Some ((first , second)) = cmd . two_args_of (| x | x . get_long () == Some (l)) { panic ! ("Command {}: Long option names must be unique for each argument, \
                            but '--{}' is in use by both '{}' and '{}'{}" , cmd . get_name () , l , first . get_id () , second . get_id () , duplicate_tip (cmd , first , second)) } } if let Some (s) = arg . get_short () { if let Some ((first , second)) = cmd . two_args_of (| x | x . get_short () == Some (s)) { panic ! ("Command {}: Short option names must be unique for each argument, \
                            but '-{}' is in use by both '{}' and '{}'{}" , cmd . get_name () , s , first . get_id () , second . get_id () , duplicate_tip (cmd , first , second) ,) } } if let Some (idx) = arg . index { if let Some ((first , second)) = cmd . two_args_of (| x | x . is_positional () && x . get_index () == Some (idx)) { panic ! ("Command {}: Argument '{}' has the same index as '{}' \
                    and they are both positional arguments\n\n\t \
                    Use `Arg::num_args(1..)` to allow one \
                    positional argument to take multiple values" , cmd . get_name () , first . get_id () , second . get_id ()) } } for (_predicate , req_id) in & arg . requires { assert ! (& arg . id != req_id , "Argument {} cannot require itself" , arg . get_id ()) ; assert ! (cmd . id_exists (req_id) , "Command {}: Argument or group '{}' specified in 'requires*' for '{}' does not exist" , cmd . get_name () , req_id , arg . get_id () ,) ; } for req in & arg . r_ifs { assert ! (! arg . is_required_set () , "Argument {}: `required` conflicts with `required_if_eq*`" , arg . get_id ()) ; assert ! (cmd . id_exists (& req . 0) , "Command {}: Argument or group '{}' specified in 'required_if_eq*' for '{}' does not exist" , cmd . get_name () , req . 0 , arg . get_id ()) ; } for req in & arg . r_ifs_all { assert ! (! arg . is_required_set () , "Argument {}: `required` conflicts with `required_if_eq_all`" , arg . get_id ()) ; assert ! (cmd . id_exists (& req . 0) , "Command {}: Argument or group '{}' specified in 'required_if_eq_all' for '{}' does not exist" , cmd . get_name () , req . 0 , arg . get_id ()) ; } for req in & arg . r_unless { assert ! (! arg . is_required_set () , "Argument {}: `required` conflicts with `required_unless*`" , arg . get_id ()) ; assert ! (cmd . id_exists (req) , "Command {}: Argument or group '{}' specified in 'required_unless*' for '{}' does not exist" , cmd . get_name () , req , arg . get_id () ,) ; } for req in & arg . r_unless_all { assert ! (! arg . is_required_set () , "Argument {}: `required` conflicts with `required_unless*`" , arg . get_id ()) ; assert ! (cmd . id_exists (req) , "Command {}: Argument or group '{}' specified in 'required_unless*' for '{}' does not exist" , cmd . get_name () , req , arg . get_id () ,) ; } for req in & arg . blacklist { assert ! (cmd . id_exists (req) , "Command {}: Argument or group '{}' specified in 'conflicts_with*' for '{}' does not exist" , cmd . get_name () , req , arg . get_id () ,) ; } for req in & arg . overrides { assert ! (cmd . id_exists (req) , "Command {}: Argument or group '{}' specified in 'overrides_with*' for '{}' does not exist" , cmd . get_name () , req , arg . get_id () ,) ; } if arg . is_last_set () { assert ! (arg . get_long () . is_none () , "Command {}: Flags or Options cannot have last(true) set. '{}' has both a long and last(true) set." , cmd . get_name () , arg . get_id ()) ; assert ! (arg . get_short () . is_none () , "Command {}: Flags or Options cannot have last(true) set. '{}' has both a short and last(true) set." , cmd . get_name () , arg . get_id ()) ; } assert ! (! (arg . is_required_set () && arg . is_global_set ()) , "Command {}: Global arguments cannot be required.\n\n\t'{}' is marked as both global and required" , cmd . get_name () , arg . get_id ()) ; if arg . get_value_hint () == ValueHint :: CommandWithArguments { assert ! (arg . is_positional () , "Command {}: Argument '{}' has hint CommandWithArguments and must be positional." , cmd . get_name () , arg . get_id ()) ; assert ! (arg . is_trailing_var_arg_set () || arg . is_last_set () , "Command {}: Positional argument '{}' has hint CommandWithArguments, so Command must have `trailing_var_arg(true)` or `last(true)` set." , cmd . get_name () , arg . get_id ()) ; } } for group in cmd . get_groups () { assert ! (cmd . get_groups () . filter (| x | x . id == group . id) . count () < 2 , "Command {}: Argument group name must be unique\n\n\t'{}' is already in use" , cmd . get_name () , group . get_id () ,) ; assert ! (! cmd . get_arguments () . any (| x | x . get_id () == group . get_id ()) , "Command {}: Argument group name '{}' must not conflict with argument name" , cmd . get_name () , group . get_id () ,) ; for arg in & group . args { assert ! (cmd . get_arguments () . any (| x | x . get_id () == arg) , "Command {}: Argument group '{}' contains non-existent argument '{}'" , cmd . get_name () , group . get_id () , arg) ; } for arg in & group . requires { assert ! (cmd . id_exists (arg) , "Command {}: Argument group '{}' requires non-existent '{}' id" , cmd . get_name () , group . get_id () , arg) ; } for arg in & group . conflicts { assert ! (cmd . id_exists (arg) , "Command {}: Argument group '{}' conflicts with non-existent '{}' id" , cmd . get_name () , group . get_id () , arg) ; } } long_flags . sort_unstable () ; short_flags . sort_unstable () ; detect_duplicate_flags (& long_flags , "long") ; detect_duplicate_flags (& short_flags , "short") ; let mut subs = FlatSet :: new () ; for sc in cmd . get_subcommands () { assert ! (subs . insert (sc . get_name ()) , "Command {}: command name `{}` is duplicated" , cmd . get_name () , sc . get_name ()) ; for alias in sc . get_all_aliases () { assert ! (subs . insert (alias) , "Command {}: command `{}` alias `{}` is duplicated" , cmd . get_name () , sc . get_name () , alias) ; } } _verify_positionals (cmd) ; # [cfg (feature = "help")] if let Some (help_template) = cmd . get_help_template () { assert ! (! help_template . to_string () . contains ("{flags}") , "Command {}: {}" , cmd . get_name () , "`{flags}` template variable was removed in clap3, they are now included in `{options}`" ,) ; assert ! (! help_template . to_string () . contains ("{unified}") , "Command {}: {}" , cmd . get_name () , "`{unified}` template variable was removed in clap3, use `{options}` instead") ; # [cfg (feature = "unstable-v5")] assert ! (! help_template . to_string () . contains ("{bin}") , "Command {}: {}" , cmd . get_name () , "`{bin}` template variable was removed in clap5, use `{name}` instead") ; } cmd . _panic_on_missing_help (cmd . is_help_expected_set ()) ; assert_app_flags (cmd) ; }
    };
}

assert_app!();